const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
if (!secret || secret.length < 32) throw new Error('LENDLOOP_SHARED_SECRET is missing or too short');
function sign(method, path, body) {
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = crypto.createHmac('sha256', secret)
    .update(`${timestamp}.${method}.${path}.${body}`).digest('hex');
  return { timestamp, signature };
}

return [{ json: sign('GET', '/n8n/overdue-loans', '') }];

// One item per overdue loan. Each already carries its idempotency key.
const loans = $input.first().json.loans || [];
return loans.map((l) => ({ json: l }));

// Mock reminder channel. Swap for Send Email / Slack. Email is masked in logs.
return $input.all().map(({ json: l }) => {
  const masked = l.borrower.email ? l.borrower.email.replace(/^(.).*(@.*)$/, '$1***$2') : 'no email';
  const text = `Hi ${l.borrower.firstName}, the ${l.toolName} was due back on ${l.dueDate} ` +
    `(${l.daysOverdue} day(s) ago). Please return it or contact the lender.`;
  console.log(`[LendLoop reminder] to=${masked} :: ${text}`);
  return { json: { loanId: l.loanId, reminderKey: l.reminderKey, sent: true } };
});

const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
if (!secret || secret.length < 32) throw new Error('LENDLOOP_SHARED_SECRET is missing or too short');
function sign(method, path, body) {
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = crypto.createHmac('sha256', secret)
    .update(`${timestamp}.${method}.${path}.${body}`).digest('hex');
  return { timestamp, signature };
}

const path = '/n8n/automation-events';
return $input.all().map(({ json: r }) => {
  const body = JSON.stringify({
    idempotencyKey: r.reminderKey,   // overdue:<loanId>:<date> -> one record per loan per day
    loanId: r.loanId,
    kind: 'overdue_reminder',
    status: r.sent ? 'sent' : 'failed',
  });
  return { json: { body, ...sign('POST', path, body) } };
});
